# v15.56: main home card, Income / Expense side by side, rounded font setting, month selector card
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block'); pg=ctx.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(2500)
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1200)
    ok('main home card has its identifier', pg.locator('section.main-home-card[data-id="main-home-card"]').count()==1)
    g=pg.evaluate("(()=>{const r=e=>e.getBoundingClientRect(),c=document.querySelector('.main-home-card'),a=c.querySelectorAll('.sc-row'),h2=parseFloat(getComputedStyle(document.createElement('h2')).fontSize),v=[...a].map(x=>x.querySelector('.sc-val')),h=document.body.appendChild(document.createElement('h2')),h2s=parseFloat(getComputedStyle(h).fontSize);h.remove();return {top:[r(a[0]).top,r(a[1]).top],left:[r(a[0]).left,r(a[1]).left],w:[r(a[0]).width,r(a[1]).width],lab:[a[0].querySelector('.sc-lab').innerText.trim(),a[1].querySelector('.sc-lab').innerText.trim()],arr:[a[0].querySelector('.sc-arr').textContent,a[1].querySelector('.sc-arr').textContent],vfs:v.map(x=>parseFloat(getComputedStyle(x).fontSize)),h2s,vy:v.map(x=>r(x).top-r(x.parentElement.querySelector('.sc-lab')).bottom)}})()")
    ok('Income and Expense are side by side %s'%g['top'], abs(g['top'][0]-g['top'][1])<1 and g['left'][1]>g['left'][0]+100)
    ok('equal widths', abs(g['w'][0]-g['w'][1])<4)
    ok('arrows beside the labels: down for Income, up for Expense', g['lab'][0].endswith('Income') and g['arr']==['↓','↑'] and g['lab'][1].endswith('Expenses'))
    ok('values are under the labels in the H2 size %s'%g['vfs'], all(abs(x-g['h2s'])<0.6 for x in g['vfs']) and all(y>=0 for y in g['vy']))
    ok('card font is the rounded one by default', 'Nunito' in pg.evaluate("getComputedStyle(document.querySelector('.main-home-card .sc-net b')).fontFamily") and pg.evaluate("document.documentElement.dataset.font")=='rounded')
    # month selector
    ok('month is one rounded card with an arrow, no left / right buttons', pg.locator('.mscard').count()==1 and pg.locator('[data-act=month]').count()==0 and pg.evaluate("parseFloat(getComputedStyle(document.querySelector('.mscard')).borderTopLeftRadius)")>=12 and pg.locator('.mscard .chev').count()==1)
    ok('closed at first', pg.locator('.mspanel:visible').count()==0 and pg.get_attribute('.mscard','aria-expanded')=='false')
    pg.click('.mscard'); pg.wait_for_timeout(200)
    ok('it expands to a year and month picker', pg.locator('.mspanel:visible').count()==1 and pg.locator('.msm').count()==12 and pg.get_attribute('.mscard','aria-expanded')=='true')
    ok('future months are disabled', pg.evaluate("[...document.querySelectorAll('.msm')].filter(x=>x.disabled).length")>=1)
    pg.click('.msyear [data-d="-1"]'); pg.wait_for_timeout(100); ok('the year can step back', pg.inner_text('.msyear b')=='2025')
    pg.click('.msm[data-m="2025-12"]'); pg.wait_for_timeout(600)
    ok('picking a month switches to it', 'December 2025' in pg.inner_text('.mscard') and pg.locator('.mspanel:visible').count()==0)
    pg.click('.mscard'); pg.mouse.click(300,700); pg.wait_for_timeout(200); ok('tapping outside closes it', pg.locator('.mspanel:visible').count()==0)
    # font setting
    pg.goto('http://localhost:8123/#/settings'); pg.wait_for_timeout(800)
    t=pg.evaluate("document.body.textContent"); ok('Settings has a Font choice', 'Rounded' in t and 'Standard' in t and 'Automatic' in t)
    pg.evaluate("document.querySelector('[data-act=look][data-k=font][data-v=standard]').click()"); pg.wait_for_timeout(500)
    ok('Standard puts the original font back', pg.evaluate("document.documentElement.dataset.font")=='standard' and 'Schibsted' in pg.evaluate("getComputedStyle(document.body).fontFamily"))
    pg.evaluate("document.querySelector('[data-act=look][data-k=font][data-v=auto]').click()"); pg.wait_for_timeout(300)
    pg.evaluate("document.querySelector('[data-act=look][data-k=design][data-v=legacy]').click()"); pg.wait_for_timeout(500)
    ok('Legacy Theme + Automatic font keeps the original font and the left / right month buttons', pg.evaluate("document.documentElement.dataset.font")=='standard')
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(900); ok('legacy header has the arrows back', pg.locator('[data-act=month]').count()==2 and pg.locator('.mscard').count()==0)
    ok('no page errors %s'%errs, not errs)
